{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE maplemonk.Category_Target_vs_Achievement AS WITH Category_Age_Mapping AS ( SELECT DISTINCT TRIM(UPPER(PRODUCT_CATEGORY)) AS PRODUCT_CATEGORY, TRIM(UPPER(COLLECTION)) AS COLLECTION, CATEGORY_AGE FROM maplemonk.zouk_secondary_sales_Consolidated WHERE CATEGORY_AGE IS NOT NULL ), Category_Level_Target AS ( SELECT TRIM(UPPER(t.Marketplace)) AS Marketplace, TRIM(UPPER(t.Category)) AS PRODUCT_CATEGORY, fsm.Collection, UPPER(fsm.Product_Type) AS Product_Type, DATE_ADD(DATE(t.Start_Date), INTERVAL n DAY) AS Target_Date, CAST(t.Target AS INT64) / (DATE_DIFF(DATE(t.End_Date), DATE(t.Start_Date), DAY) + 1) AS Target, CASE WHEN CURRENT_DATE() > DATE_ADD(DATE(t.Start_Date), INTERVAL n DAY) THEN 0 ELSE DATE_DIFF(LAST_DAY(DATE_ADD(DATE(t.Start_Date), INTERVAL n DAY)), CURRENT_DATE(), DAY) + 1 END AS days_Remaining, EXTRACT(DAY FROM LAST_DAY(DATE_ADD(DATE(t.Start_Date), INTERVAL n DAY))) AS no_of_days FROM maplemonk.Zouk_Category_Level_Target t LEFT JOIN ( SELECT * FROM maplemonk.final_sku_master QUALIFY ROW_NUMBER() OVER (PARTITION BY LOWER(CATEGORY) ORDER BY IFNULL(collection, \'\') DESC) = 1 ) fsm ON LOWER(fsm.CATEGORY) = LOWER(t.CATEGORY) CROSS JOIN UNNEST(GENERATE_ARRAY(0, DATE_DIFF(DATE(t.End_Date), DATE(t.Start_Date), DAY))) AS n ) , Daily_Achievements AS ( SELECT TRIM(UPPER(s.Marketplace)) AS Marketplace, TRIM(UPPER(s.PRODUCT_CATEGORY)) AS PRODUCT_CATEGORY, TRIM(UPPER(s.COLLECTION)) AS Collection, TRIM(UPPER(s.product_type)) AS Product_Type, DATE(s.Order_Date) AS Achievement_Date, SUM(IFNULL(s.QUANTITY,0)) AS Quantity, SUM(IFNULL(s.Selling_Price, 0)) AS Achievement FROM maplemonk.zouk_secondary_sales_Consolidated s WHERE NOT (LOWER(IFNULL(ORDER_STATUS,\'\')) LIKE \'%cancel%\' OR LOWER(IFNULL(FINAL_SHIPPING_STATUS,\'\')) LIKE \'%cancel%\') AND DATE(s.Order_Date) < CURRENT_DATE() GROUP BY 1, 2, 3, 4, 5 ), Daily_Spends AS ( SELECT TRIM(UPPER(Marketplace)) AS Marketplace, TRIM(UPPER(PRODUCT_CATEGORY)) AS PRODUCT_CATEGORY, TRIM(UPPER(COLLECTION)) AS Collection, TRIM(UPPER( CASE WHEN PRODUCT_TYPE IS NULL OR TRIM(PRODUCT_TYPE) = \'\' THEN COLLECTION ELSE PRODUCT_TYPE END )) AS Product_Type, DATE(Date) AS Spend_Date, SUM(IFNULL(Spend, 0)) AS Spend, SUM(IFNULL(BAU_MRP_SALES,0)) AS BAU_MRP_SALES, SUM(IFNULL(return_mrp_sales,0)) AS return_mrp_sales, SUM(IFNULL(BAU_DISCOUNT,0)) AS BAU_DISCOUNT, SUM(IFNULL(TRADE_MARGIN,0)) AS TRADE_MARGIN, SUM(IFNULL(return_trade_margin,0)) AS return_trade_margin, SUM(IFNULL(Returns,0)) AS Returns, SUM(IFNULL(gst,0)) AS gst, SUM(IFNULL(Return_GST,0)) AS Return_GST, SUM(IFNULL(cogs,0)) AS cogs, SUM(IFNULL(return_cogs,0)) AS return_cogs FROM maplemonk.zouk_secondary_pandl GROUP BY 1, 2, 3, 4, 5 ), Combined_Data AS ( SELECT COALESCE(COALESCE(dt.Target_Date, da.Achievement_Date), ds.Spend_Date) AS Date, COALESCE(COALESCE(dt.Marketplace, da.Marketplace), ds.Marketplace) AS Marketplace, COALESCE(COALESCE(dt.PRODUCT_CATEGORY, da.PRODUCT_CATEGORY), ds.PRODUCT_CATEGORY) AS PRODUCT_CATEGORY, COALESCE(COALESCE(dt.Collection, da.Collection),ds.Collection) AS Collection, COALESCE(COALESCE(dt.Product_Type, da.Product_Type), ds.Product_Type) AS Product_Type, da.Quantity, dt.Target, dt.days_Remaining, dt.no_of_days, COALESCE(da.Achievement, 0) AS Achievement, COALESCE(ds.Spend, 0) AS Spend, COALESCE(ds.BAU_MRP_SALES,0) AS BAU_MRP_SALES, COALESCE(ds.return_mrp_sales,0) AS return_mrp_sales, COALESCE(ds.BAU_DISCOUNT,0) AS BAU_DISCOUNT, COALESCE(ds.TRADE_MARGIN,0) AS TRADE_MARGIN, COALESCE(ds.return_trade_margin,0) AS return_trade_margin, COALESCE(ds.Returns,0) AS Returns, COALESCE(ds.gst,0) AS gst, COALESCE(ds.Return_GST,0) AS Return_GST, COALESCE(ds.cogs,0) AS cogs, COALESCE(ds.return_cogs) AS return_cogs FROM Category_Level_Target dt FULL OUTER JOIN Daily_Achievements da ON TRIM(dt.Marketplace) = TRIM(da.Marketplace) AND TRIM(dt.PRODUCT_CATEGORY) = TRIM(da.PRODUCT_CATEGORY) AND TRIM(dt.Collection) = TRIM(da.Collection) AND dt.Target_Date = da.Achievement_Date FULL OUTER JOIN Daily_Spends ds ON TRIM(dt.Marketplace) = TRIM(ds.Marketplace) AND TRIM(dt.PRODUCT_CATEGORY) = TRIM(ds.PRODUCT_CATEGORY) AND TRIM(dt.Collection) = TRIM(ds.Collection) AND dt.Target_Date = ds.Spend_Date ), Final_Data AS ( SELECT cd.Date, cd.Marketplace, cd.PRODUCT_CATEGORY, cd.Collection, cd.Product_Type, cd.Target, cd.Achievement, cd.Spend, cd.Quantity, cd.BAU_MRP_SALES, cd.return_mrp_sales, cd.BAU_DISCOUNT, cd.TRADE_MARGIN, cd.return_trade_margin, cd.Returns, cd.Return_GST, cd.gst, cd.cogs, cd.return_cogs, cd.days_Remaining, cd.no_of_days, mm.FINAL_MARKETPLACE, mm.Marketplace_Segments, mm.Channel, ca.Category_Age, CASE WHEN mm.Marketplace IS NULL THEN \'Missing in Marketplace Mapping\' ELSE \'Found\' END AS Mapping_Status FROM Combined_Data cd LEFT JOIN ( SELECT * FROM maplemonk.Zouk_New_Marketplace_Mapping QUALIFY ROW_NUMBER() OVER (PARTITION BY LOWER(TRIM(marketplace)) ORDER BY 1) = 1 ) mm ON LOWER(TRIM(cd.Marketplace)) = LOWER(TRIM(mm.Marketplace)) LEFT JOIN Category_Age_Mapping ca ON cd.PRODUCT_CATEGORY = ca.PRODUCT_CATEGORY AND cd.Collection = ca.COLLECTION ) SELECT Date, Marketplace, PRODUCT_CATEGORY, Collection, Product_Type, Target, Achievement, Spend, Quantity, BAU_MRP_SALES, return_mrp_sales, BAU_DISCOUNT, TRADE_MARGIN, return_trade_margin, Returns, Return_GST, gst, cogs, return_cogs, days_Remaining, no_of_days, FINAL_MARKETPLACE, Marketplace_Segments, Channel, CATEGORY_AGE FROM Final_Data ORDER BY Date, Marketplace, PRODUCT_CATEGORY",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            